before:
Complete local C++ example; the app itself does not execute it:
```cpp
#include <iostream>
#include <memory>
#include <utility>
int main() {
    auto p = std::make_unique<int>(7);
    auto q = std::move(p);
    std::cout << std::boolalpha << (p == nullptr) << '\n';
    if (q) std::cout << *q << '\n';
}

```

